const ABOUT_DATA={summary:`I'm a <i>Computer Science student</i> at <b>SZABIST University</b>, with a solid\n        background in <i>OOP with Java</i> and <i>C programming</i>. I focus on developing\n        sound logical reasoning and writing clean, organized code. I'm studying the\n        <i>game development pipeline</i> — from system design and core programming ideas to\n        gameplay logic — because I see it as a technical and problem-solving discipline, not\n        just a tool-based skill. Alongside that, I work on web development projects to sharpen\n        my understanding of design principles, user interaction, and front-end technologies.`,experience:[{title:"Front-end AI Engineering Intern",org:"FlyRank AI",period:"July 2026 – Present",desc:"Working on the front-end side of AI-driven products, translating product ideas into real, working interfaces."},{title:"Web Developer",org:"ALLTASKER",period:"November 2025 – August 2026",desc:"Built React and WordPress websites for clients with a strong emphasis on SEO-driven architecture — from first line of code to full site delivery."},{title:"WordPress Developer",org:"Sysartx (Internship)",period:"July 2025 – September 2025",desc:"Built and customized responsive WordPress sites, designed and modified themes with HTML/CSS/PHP/JS, integrated plugins, and contributed to SEO and performance optimization."}],education:`<b>SZABIST University:</b><br><i>BS Computer Science</i> (Sep 2024 – Dec 2028)<br>\n        <b>Govt. Degree College Boys and Girls SRE III Majeed:</b><br>\n        <i>Intermediate, Pre-Engineering</i> (Jun 2022 – Jul 2024)<br>\n        <b>Arqam Public School:</b><br><i>Matric, Computer Science</i> (May 2020 – May 2022)`,skills:[{label:"Godot & Unity (Game Development)",value:68},{label:"React (Component-Based UI)",value:75},{label:"WordPress & PHP",value:82},{label:"Java & C Programming (OOP)",value:80},{label:"HTML, CSS & JavaScript",value:85},{label:"Critical Thinking & Problem-Solving",value:85},{label:"Git & Version Control",value:72}],certifications:["AI for Beginners","Query Quest — Certificate of Achievement","What is Artificial Intelligence? — HackerRank"],languages:`English: Fluent <br><br> Urdu: Native`};function renderSkillBar(e){const n=Math.max(0,Math.min(100,e.value));return`\n        <div class="skill-item">\n            <div class="skill-track" role="progressbar" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="100" aria-label="${e.label}">\n                <div class="skill-fill" style="width: ${n}%;"></div>\n            </div>\n            <p class="skill-label">${e.label}</p>\n        </div>`}function renderExperienceEntry(e){return`\n        <div class="experience-item">\n            <p class="about-text"><b>${e.title}</b> — ${e.org}<br>\n            <span class="experience-period">${e.period}</span><br>\n            ${e.desc}</p>\n        </div>`}function renderAboutSection(){const e=ABOUT_DATA.skills.map(renderSkillBar).join("");const n=ABOUT_DATA.experience.map(renderExperienceEntry).join("<br>");const i=ABOUT_DATA.certifications.map(function(e){return`<li>${e}</li>`}).join("");return`\n        <section id="about" class="reveal">\n            <h2>ABOUT</h2>\n            <br>\n            <div>\n                <h3 id="topic">SUMMARY</h3>\n                <br>\n                <p class="about-text">${ABOUT_DATA.summary}</p>\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">EXPERIENCE</h3>\n                <br>\n                ${n}\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">EDUCATION</h3>\n                <br>\n                <p class="about-text">${ABOUT_DATA.education}</p>\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">SKILLS</h3>\n                <br>\n                ${e}\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">CERTIFICATIONS</h3>\n                <br>\n                <ul class="about-text certifications-list">${i}</ul>\n            </div>\n            <br>\n            <div>\n                <h3 id="topic">LANGUAGES</h3>\n                <br>\n                <p class="about-text">${ABOUT_DATA.languages}</p>\n            </div>\n        </section>`}document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("about-mount");if(e){e.innerHTML=renderAboutSection()}});
